def sparse_top_k_categorical_accuracy(y_true, y_pred, k=5):
    # Convert y_true to rank-1 tensor
    y_true = K.flatten(y_true)
    return K.mean(K.in_top_k(y_pred, K.cast(y_true, 'int32'), k), axis=-1)
```

